// 1. Trích xuất an toàn payload từ RabbitMQ message
const item = $input.first().json;
let payload = {};

if (item.content) {
  try {
    payload = typeof item.content === 'string' ? JSON.parse(item.content) : item.content;
  } catch (err) {
    payload = {};
  }
} else {
  payload = item;
}

// Support wrapped event ({ data: { ... } }) and flat event
const eventData = payload.data || payload;
const leadId = eventData.leadId || payload.leadId || null;
const workflowRunId = eventData.workflowRunId || payload.workflowRunId || null;

// Data bundle aggregated by NestJS
const lead = eventData.leadData || eventData.lead || {};
const qual = eventData.qualificationData || eventData.qualification || null;
const enrich = eventData.enrichmentData || eventData.enrichment || null;
const interactions = eventData.interactions || [];
const scoringContext = eventData.scoringContext || {};
const features = scoringContext.scoringFeatures || {};

// 2. Build structured prompt context for AI Scoring Model
const fullName = `${lead.firstName || ''} ${lead.lastName || ''}`.trim() || 'Unknown';
const jobTitle = enrich?.contactJobTitle || lead.jobTitle || 'Unknown';
const companyName = enrich?.companyName || lead.companyName || 'Unknown';
const companyWebsite = enrich?.companyWebsite || lead.companyWebsite || 'None';
const industry = enrich?.companyIndustry || lead.industry || 'Unknown';
const companySize = enrich?.companySize ?? lead.companySize ?? 'Unknown';

const prompt = `
You are an enterprise AI Lead Scoring model. Evaluate and score the following prospective lead for sales readiness.

=== LEAD PROFILE ===
- Full Name: ${fullName}
- Email: ${lead.email || 'N/A'}
- Job Title: ${jobTitle}
- Company: ${companyName}
- Website: ${companyWebsite}
- Industry: ${industry}
- Company Size (Employees): ${companySize}
- Current CRM Status: ${lead.status || 'NEW'}
- Notes: ${lead.notes || 'None'}

=== AI QUALIFICATION DATA ===
- Status: ${qual?.status || 'NOT_QUALIFIED'}
- Confidence: ${qual?.confidence != null ? Math.round(qual.confidence * 100) + '%' : 'N/A'}
- Intent Summary: ${qual?.intent || 'N/A'}
- Qualification Reason: ${qual?.reason || 'N/A'}

=== DATA ENRICHMENT DATA ===
- Provider: ${enrich?.provider || 'None'}
- Status: ${enrich?.status || 'NOT_ENRICHED'}
- Verified Company: ${enrich?.companyName || 'Not verified'}
- Verified Size: ${enrich?.companySize != null ? enrich.companySize : 'Not available'}

=== INTERACTION HISTORY ===
- Total Touchpoints: ${interactions.length}
- Touchpoints Summary:
${interactions.map((i, idx) => `  ${idx + 1}. [${i.occurredAt || 'Recent'}] (${i.type || 'INTERACTION'}/${i.channel || 'direct'}) ${i.subject || ''}: ${i.content || ''}`).slice(0, 5).join('\n') || '  No interactions recorded.'}

=== SCORING GUIDELINES (0 - 100) ===
- HOT (>= 75): High purchase intent, verified decision maker (Director/VP/C-Level), target enterprise or scale-up company (>= 50 employees), frequent interactions, qualified status.
- WARM (40 - 74): Moderate fit, mid-level professional, small-medium business, active or neutral qualification, early engagement.
- COLD (< 40): Low intent, disqualified, missing critical business profile, individual/free email without company, no engagement.
`;

return [{
  json: {
    leadId,
    workflowRunId,
    prompt,
    leadBundle: {
      lead,
      qualification: qual,
      enrichment: enrich,
      interactions,
      features
    },
    rawEvent: payload
  }
}];

// Multi-factor Deterministic & AI Scoring Engine
const item = $input.first().json;
const leadId = item.leadId;
const workflowRunId = item.workflowRunId;
const bundle = item.leadBundle || {};
const lead = bundle.lead || {};
const qual = bundle.qualification;
const enrich = bundle.enrichment;
const interactions = bundle.interactions || [];
const f = bundle.features || {};

// Base score
let calculatedScore = 20;
const scoringFeatures = {
  baseScore: 20,
  profileFitPoints: 0,
  decisionMakerPoints: 0,
  qualificationPoints: 0,
  engagementPoints: 0,
  enrichmentBonus: 0
};

// 1. Profile Fit & Company Size (Max 20 points)
const companySize = enrich?.companySize ?? lead.companySize;
if (typeof companySize === 'number') {
  if (companySize >= 100) {
    scoringFeatures.profileFitPoints = 20;
  } else if (companySize >= 20) {
    scoringFeatures.profileFitPoints = 15;
  } else if (companySize >= 5) {
    scoringFeatures.profileFitPoints = 10;
  } else {
    scoringFeatures.profileFitPoints = 5;
  }
} else if (lead.companyName || enrich?.companyName) {
  scoringFeatures.profileFitPoints = 10;
}

// 2. Decision Maker / Authority (Max 20 points)
const jobTitle = (enrich?.contactJobTitle || lead.jobTitle || '').toLowerCase();
const decisionKeywords = ['ceo', 'cto', 'cfo', 'coo', 'cmo', 'cio', 'vp', 'director', 'founder', 'owner', 'head of', 'lead'];
if (decisionKeywords.some((kw) => jobTitle.includes(kw))) {
  scoringFeatures.decisionMakerPoints = 20;
} else if (jobTitle.length > 0) {
  scoringFeatures.decisionMakerPoints = 10;
}

// 3. AI Qualification Result (Max 25 points, or -20 for Disqualified)
if (qual && qual.status === 'QUALIFIED') {
  const conf = typeof qual.confidence === 'number' ? qual.confidence : 0.85;
  scoringFeatures.qualificationPoints = Math.round(conf * 25);
} else if (qual && qual.status === 'DISQUALIFIED') {
  scoringFeatures.qualificationPoints = -20;
} else if (qual && qual.status === 'NEEDS_REVIEW') {
  scoringFeatures.qualificationPoints = 10;
}

// 4. Engagement & Touchpoint Activity (Max 25 points)
const recentInteractions = interactions.length;
scoringFeatures.engagementPoints = Math.min(25, recentInteractions * 8);

// 5. Enrichment bonus (Max 10 points)
if (enrich && enrich.status === 'SUCCESS') {
  scoringFeatures.enrichmentBonus = 10;
}

calculatedScore += 
  scoringFeatures.profileFitPoints +
  scoringFeatures.decisionMakerPoints +
  scoringFeatures.qualificationPoints +
  scoringFeatures.engagementPoints +
  scoringFeatures.enrichmentBonus;

// Clamp score between 0 and 100
const finalScore = Math.max(0, Math.min(100, Math.round(calculatedScore)));

// Enforce business labeling rule:
// HOT >= 75 | WARM 40 - 74 | COLD < 40
let label = 'COLD';
if (finalScore >= 75) {
  label = 'HOT';
} else if (finalScore >= 40) {
  label = 'WARM';
}

// Construct explainable justification reason
const reasons = [];
if (scoringFeatures.decisionMakerPoints >= 15) {
  reasons.push(`Decision-maker title ('${jobTitle}')`);
}
if (scoringFeatures.profileFitPoints >= 15) {
  reasons.push(`Target enterprise size (${companySize} employees)`);
}
if (scoringFeatures.qualificationPoints >= 15) {
  reasons.push(`AI qualified with high confidence`);
} else if (scoringFeatures.qualificationPoints < 0) {
  reasons.push(`Previously disqualified`);
}
if (scoringFeatures.engagementPoints >= 10) {
  reasons.push(`${interactions.length} recorded interactions`);
}
if (reasons.length === 0) {
  reasons.push('Standard inbound profile evaluation');
}

const reason = `[${label} - Score ${finalScore}/100] ${reasons.join(', ')}.`;

return [{
  json: {
    leadId,
    workflowRunId,
    status: 'SUCCESS',
    score: finalScore,
    label,
    reason,
    scoringFeatures,
    modelInfo: {
      provider: 'crm-ai-engine',
      model: 'lead-scorer-gpt-4o',
      version: '2024-08-06'
    },
    inputOutputSnapshot: {
      input: {
        leadId,
        prompt: item.prompt,
        leadProfile: lead,
        qualification: qual,
        enrichment: enrich,
        interactionCount: interactions.length
      },
      output: {
        score: finalScore,
        label,
        scoringFeatures,
        reason
      }
    }
  }
}];

// Validate & Enforce Business Constraints on Output
const item = $input.first().json;

if (item.status === 'FAILED') {
  return [{
    json: {
      leadId: item.leadId,
      workflowRunId: item.workflowRunId,
      status: 'FAILED',
      errorMessage: item.errorMessage || 'AI Lead scoring failed'
    }
  }];
}

// 1. Clamp score strictly 0 - 100
let score = Number(item.score);
if (isNaN(score)) {
  score = 0;
}
score = Math.max(0, Math.min(100, Math.round(score * 100) / 100));

// 2. Strict Label assignment rule:
// HOT >= 75 | WARM 40 - 74 | COLD < 40
let label = 'COLD';
if (score >= 75) {
  label = 'HOT';
} else if (score >= 40) {
  label = 'WARM';
}

return [{
  json: {
    leadId: item.leadId,
    workflowRunId: item.workflowRunId,
    status: 'SUCCESS',
    score,
    label,
    reason: item.reason || `AI evaluated score: ${score}`,
    scoringFeatures: item.scoringFeatures || {},
    modelInfo: item.modelInfo || {
      provider: 'crm-ai-engine',
      model: 'lead-scorer-gpt-4o',
      version: '2024-08-06'
    },
    inputOutputSnapshot: item.inputOutputSnapshot || {}
  }
}];

